// Authored Navi hint fixture; no game data.
using HookshotAdventure.Core;
using System.IO.Compression;
using System.Security.Cryptography;
static class NaviFixtures
{
    public static void Check()
    {
        using var input = new ZLibStream(new MemoryStream(Convert.FromBase64String("")), CompressionMode.Decompress);
        using var output = new MemoryStream(); input.CopyTo(output);
        var original = output.ToArray();
        string[] names = ["Scrub_Deku", "Dekubaba_Withered", "Dekubaba", "Skullwalltula", "Gohma_Egg", "Gohma_Larva"];
        var patched = HAL_ConversationSkips.PatchDekuNaviHints(original, names);
        AssertTest.True(Convert.ToHexString(SHA256.HashData(patched)) == "9D7E63DEE243516C7CC12378ACC67383A00F071E60E30B2BB6019FA9CB85CFD1", "Navi hint edits match Python");
        bool rejected = false;
        try { HAL_ConversationSkips.PatchDekuNaviHints(patched, names); } catch (InvalidDataException) { rejected = true; }
        AssertTest.True(rejected, "Navi hint edits reject altered entries");
    }
}
